using FlexExtractor;
using System.Reflection;
static partial class Cases {
 public static void TestServiceStartupErrorSetsNonzeroExit(){var old=Environment.ExitCode;Environment.ExitCode=0;try{var ctor=typeof(FlexExtractor.Service.ServiceWorker).GetConstructor(new[]{typeof(Func<Config>)});Program.Check(ctor!=null,"self-test must not load the deployment configuration");using var worker=(FlexExtractor.Service.ServiceWorker)ctor!.Invoke(new object[]{(Func<Config>)(()=>throw new FileNotFoundException("isolated startup config fault"))});try{worker.StartAsync(CancellationToken.None).GetAwaiter().GetResult();}catch(FileNotFoundException){}Program.Check(Environment.ExitCode!=0,"service startup failure disguised as success");}finally{Environment.ExitCode=old;}}
 public static void TestSelfTestEntryPointsExistBeforeUiOrService(){var t=typeof(Config).Assembly.GetType("FlexExtractor.SelfTests");Program.Check(t!=null,"shared self-test launcher missing");Program.Check(t!.GetMethod("Run")!=null,"self-test run missing");}
 public static void TestServiceHostIsHeadlessAndSharedEngine(){var path=Path.Combine(AppContext.BaseDirectory,"FlexRequestExtractor.Service.dll");Program.Check(File.Exists(path),"Windows service host missing");var asm=Assembly.LoadFrom(path);var worker=asm.GetType("FlexExtractor.Service.ServiceWorker");Program.Check(worker!=null&&worker.BaseType!.Name=="BackgroundService","native hosted service missing");Program.Check(!asm.GetReferencedAssemblies().Any(a=>a.Name=="System.Windows.Forms"),"service depends on UI");Program.Check(worker!.GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic)!.FieldType==typeof(Engine),"host not using shared engine");}
}
